    message "Expected a type variable after the variance annotation" 
# 7015 "boot/lrgrep/parse_errors.ml"
    )
  | 558, _ ->
    Some (
# 3041 "parsing/parse_errors.lrgrep"
    message "Expected a type name after `type`" 
# 7021 "boot/lrgrep/parse_errors.ml"
    )
  | 559, _ ->
    Some (
# 3053 "parsing/parse_errors.lrgrep"
    message "Expected a type name after the type parameters" 
# 7027 "boot/lrgrep/parse_errors.ml"
    )
  | 560, _ ->
    let lp, _startpos_lp_, _endpos_lp_, _positions_lp_ = match __registers.(0) with 
      | Empty -> assert false
      | Location _ -> assert false
      | Value (Parser.MenhirInterpreter.Element (st, x, startp, endp)) ->
        let x = match Parser.MenhirInterpreter.incoming_symbol st with
          | T T_LPAREN -> (x : unit)
          | _ -> assert false
        in
        (x, startp, endp, (startp, endp))
    in
    let _ = lp in
    Some (
# 3057 "parsing/parse_errors.lrgrep"
    message "Unclosed parenthesis"
      ~sub:[ mkloc _startpos_lp_ _endpos_lp_, "opened here" ] 
# 7045 "boot/lrgrep/parse_errors.ml"
    )
  | _ -> failwith "Invalid action (internal error or API misuse)"

let error_messages  _lrgrep_env _lrgrep_lookahead = (
  let lrgrep_execute = lrgrep_execute_error_messages  _lrgrep_env _lrgrep_lookahead in
      List.find_map lrgrep_execute
    (lrgrep_run_with_depths lrgrep_program_error_messages _lrgrep_env)
)

